# %% [code]
"""
=============================================================================
ARC-AGI-3 SOVEREIGN ACTIVE INFERENCE SUBMISSION KERNEL
Competition: arc-prize-2026-arc-agi-3
=============================================================================
1. Installs competition wheels (offline).
2. Waits for hidden evaluation gateway (http://gateway:8001).
3. Unpacks full Sovereign Agent (SMDP Options, Active Inference, Inducers).
4. Launches SovereignARC3Agent via official evaluation harness.
5. In commit / non-rerun mode: emits valid submission.parquet.
=============================================================================
"""

import os
import sys
import glob
import time
import io
import tarfile
import base64
import subprocess
import pandas as pd

print("=== [ARC-AGI-3 SOVEREIGN SUBMISSION PIPELINE] ===")

is_rerun = os.getenv('KAGGLE_IS_COMPETITION_RERUN') is not None
print(f"[+] Competition rerun mode: {is_rerun}")

if is_rerun:
    print("[*] Phase 1: Installing offline dependencies from competition wheels...")
    wheel_dirs = glob.glob('/kaggle/input/**/arc_agi_3_wheels', recursive=True)
    if wheel_dirs:
        print(f"[+] Found wheels directory: {wheel_dirs[0]}")
        subprocess.run(
            f"pip install --no-index --find-links {wheel_dirs[0]} arc-agi python-dotenv",
            shell=True, check=True
        )
    else:
        print("[!] Searching for fallback wheels path...")
        fallback_path = "/kaggle/input/competitions/arc-prize-2026-arc-agi-3/arc_agi_3_wheels"
        subprocess.run(
            f"pip install --no-index --find-links {fallback_path} arc-agi python-dotenv",
            shell=True, check=True
        )

    print("[*] Phase 2: Waiting for hidden test gateway...")
    subprocess.run(
        "curl --fail --retry 999 --retry-all-errors --retry-delay 5 --retry-max-time 600 http://gateway:8001/api/games",
        shell=True, check=True
    )
    print("[+] Gateway connection established.")

    print("[*] Phase 3: Setting up ARC-AGI-3-Agents environment...")
    repos = glob.glob('/kaggle/input/**/ARC-AGI-3-Agents', recursive=True)
    repo_src = repos[0] if repos else '/kaggle/input/competitions/arc-prize-2026-arc-agi-3/ARC-AGI-3-Agents'
    
    target_repo = '/kaggle/working/ARC-AGI-3-Agents'
    subprocess.run(f"cp -r {repo_src} {target_repo}", shell=True, check=True)

    print("[*] Phase 4: Unpacking Sovereign ARC-3 Agent & Causal Engine...")
    SOVEREIGN_PAYLOAD_B64 = ""

    payload_bytes = base64.b64decode(SOVEREIGN_PAYLOAD_B64.encode('ascii'))
    with tarfile.open(fileobj=io.BytesIO(payload_bytes), mode='r:gz') as tar:
        tar.extractall(path=target_repo)
    print(f"[+] Unpacked Sovereign Agent into {target_repo}.")

    # Expose SovereignARC3Agent in agents/templates/sovereign_agent.py
    wrapper_code = """import os
import sys

repo_root = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
if repo_root not in sys.path:
    sys.path.insert(0, repo_root)

from my_agent import SovereignARC3Agent
"""
    with open(f"{target_repo}/agents/templates/sovereign_agent.py", "w") as f:
        f.write(wrapper_code)

    # Write sterilized agents/__init__.py
    init_code = """from typing import Type
from dotenv import load_dotenv
from .agent import Agent, Playback
from .swarm import Swarm
from .templates.random_agent import Random
from .templates.sovereign_agent import SovereignARC3Agent

load_dotenv()

AVAILABLE_AGENTS: dict[str, Type[Agent]] = {
    "random": Random,
    "sovereign": SovereignARC3Agent,
}
"""
    with open(f"{target_repo}/agents/__init__.py", "w") as f:
        f.write(init_code)

    # Write .env configuration
    env_code = """SCHEME=http
HOST=gateway
PORT=8001
ARC_API_KEY=test-key-123
ARC_BASE_URL=http://gateway:8001/
OPERATION_MODE=online
ENVIRONMENTS_DIR=
RECORDINGS_DIR=/kaggle/working/server_recording
"""
    with open(f"{target_repo}/.env", "w") as f:
        f.write(env_code)

    print("[*] Phase 5: Launching Sovereign Agent Swarm on evaluation games...")
    cmd = f"cd {target_repo} && MPLBACKEND=agg python main.py --agent sovereign"
    res = subprocess.run(cmd, shell=True)
    print(f"[+] Agent run completed with exit code: {res.returncode}")

else:
    print("[*] Non-rerun mode detected: Emitting valid dummy submission.parquet for validation pass...")
    out_dir = '/kaggle/working' if os.path.exists('/kaggle') else '.'
    os.makedirs(out_dir, exist_ok=True)
    out_file = os.path.join(out_dir, 'submission.parquet')
    submission = pd.DataFrame(
        data=[['1_0', '1', True, 1]],
        columns=['row_id', 'game_id', 'end_of_game', 'score']
    )
    submission.to_parquet(out_file, index=False)
    print(f"[+] Successfully wrote dummy submission to {out_file}")

print("=== [PIPELINE EXECUTION COMPLETE] ===")
